Code.Terraform:
```hcl
# Name the roles AgentCore may be handed
resource "aws_iam_policy" "<example_resource_name>" {
  name   = "<example_resource_name>"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = ["iam:PassRole"]
      # FIX: replace '*' with the execution roles AgentCore is meant to run as
      Resource  = "arn:aws:iam::${var.account_id}:role/<example_resource_id>*"
      Condition = {
        StringEquals = { "iam:PassedToService" = "bedrock-agentcore.amazonaws.com" }
      }
    }]
  })
}
